+        .disable()
+        .httpBasic()
+        .and()
+        .authenticationProvider(preauthAuthProvider())
+        .authorizeRequests()
+        .antMatchers(HttpMethod.GET, "/docs/**")
+        .permitAll()
+        .and()
+        .addFilter(preAuthFilter())
+        .addFilterAfter(new ElytronToJaasFilter(), JaasApiIntegrationFilter.class)
+        .addFilter(jaasApiIntegrationFilter());
